import type { InjectionKey } from "vue";
import type { ToolCallMeta } from "./types";

export type ToolCallGroupApi = {
  register: (get: () => ToolCallMeta) => void;
  unregister: (get: () => ToolCallMeta) => void;
};

export const TOOL_CALL_GROUP_KEY: InjectionKey<ToolCallGroupApi> = Symbol("va-tool-call-group");

/** VaToolCallCard / VaToolCallGroup 的类型定义 */

export type ToolCallStatus = "running" | "success" | "error";

export interface ToolCallCardProps {
  /** 工具名，等宽展示，如 search_web */
  name: string;
  /** 一句人话摘要 */
  summary?: string;
  status: ToolCallStatus;
  /** 调用参数：对象会被美化，JSON 字符串会被解析后美化 */
  args?: unknown;
  /** 返回结果：同上 */
  result?: unknown;
  /** status 为 error 时展示的错误信息 */
  error?: string;
  /** 开始时间（ms 时间戳），running 态的实时计时起点 */
  startedAt?: number;
  /** 最终耗时 ms；不传时由组件在结束时测量 */
  duration?: number;
  /** 参数/结果超出该高度后折叠，点击展开 */
  maxCodeHeight?: number;
  /** 失败时自动展开、下次运行自动收起（用户手动操作过则不干预） */
  openOnError?: boolean;
  /** 初始展开（父层未绑定 v-model:open 时生效） */
  defaultOpen?: boolean;
  /** 受控展开状态（配合 @update:open 实现 v-model:open） */
  open?: boolean;
}

export interface ToolCallCardEvents {
  retry: [];
  "update:open": [v: boolean];
}

export interface ToolCallGroupProps {
  /** 全部结束后的标签，默认"使用了 N 个工具" */
  label?: string;
  /** 有卡在跑时的标签，默认"正在执行工具…" */
  runningLabel?: string;
  /** 总耗时 ms；不传时由组件汇总各卡的耗时 */
  duration?: number;
  /** 初始展开（父层未绑定 v-model:open 时生效） */
  defaultOpen?: boolean;
  /** 受控展开状态（配合 @update:open 实现 v-model:open） */
  open?: boolean;
}

export interface ToolCallGroupEvents {
  "update:open": [v: boolean];
}

/** VaToolCallCard 向外层 VaToolCallGroup 注册的元信息 */
export interface ToolCallMeta {
  name: string;
  status: ToolCallStatus;
  /** 结束后的最终耗时；running 时为 undefined */
  duration?: number;
  hasIcon: boolean;
}

import { computed, inject, onBeforeUnmount, onMounted, ref, watch } from "vue";
import { TOOL_CALL_GROUP_KEY } from "./context";
import type { ToolCallCardProps } from "./types";
import { formatMs, toDisplayText } from "../../utils/format";
import { useNow } from "../../composables/useNow";

/**
 * VaToolCallCard 的状态逻辑：
 * - running 态实时计时（共享 useNow 时钟）
 * - 失败自动展开、下次运行自动收起（用户手动操作过则不干预）
 * - 参数/结果展示文本与折叠
 * - 元信息上报给外层 VaToolCallGroup
 */
export function useToolCallCard(
  props: ToolCallCardProps,
  emitUpdateOpen: (v: boolean) => void,
) {
  /* ---------- 分组注册 ---------- */
  const group = inject(TOOL_CALL_GROUP_KEY, null);

  /**
   * 展开状态三段判定：
   * 1) 父层绑定 v-model:open（props.open !== undefined）→ 受控跟随父层
   * 2) 组件内被点过/自动展开过 → 用内部值
   * 3) 从未操作 → 回落 defaultOpen
   * （不用 defineModel：Vue 对 Boolean prop 有 cast，未绑定时其本地值为 false，无法区分"未绑定"与"绑定 false"）
   */
  const innerOpen = ref(false);
  const openTouched = ref(false);
  const isOpen = computed(() => {
    if (props.open !== undefined) return props.open;
    if (openTouched.value) return innerOpen.value;
    return props.defaultOpen ?? false;
  });
  function setOpen(v: boolean) {
    openTouched.value = true;
    innerOpen.value = v;
    emitUpdateOpen(v);
  }

  /* ---------- 计时 ---------- */
  const isRunning = computed(() => props.status === "running" && props.startedAt != null);
  const now = useNow(200, isRunning);
  const stoppedAt = ref<number | undefined>(undefined);

  watch(isRunning, (v) => {
    if (!v) stoppedAt.value = elapsedRaw.value || undefined;
  });

  const elapsedRaw = computed(() => (props.startedAt != null ? Math.max(0, now.value - props.startedAt) : 0));

  const timeMs = computed(() => {
    if (props.status === "running") return elapsedRaw.value;
    if (props.duration != null) return props.duration;
    return stoppedAt.value ?? 0;
  });
  const timeLabel = computed(() => formatMs(timeMs.value));

  /* ---------- 失败自动展开 ---------- */
  const autoOpened = ref(false);
  watch(
    () => props.status,
    (to, from) => {
      if (!props.openOnError || openTouched.value) return;
      if (to === "error" && from !== "error" && !isOpen.value) {
        setOpen(true);
        autoOpened.value = true;
      } else if (from === "error" && to !== "error" && autoOpened.value) {
        setOpen(false);
        autoOpened.value = false;
      }
    },
  );

  function toggle() {
    setOpen(!isOpen.value);
  }

  /* ---------- 内容 ---------- */
  const argsText = computed(() => toDisplayText(props.args));
  const resultText = computed(() => (props.status === "error" ? "" : toDisplayText(props.result)));
  const expanded = ref<Record<string, boolean>>({});
  function isLong(text: string) {
    return text.length > 400;
  }

  /* ---------- 元信息上报 ---------- */
  const id = `va-tcl-${Math.random().toString(36).slice(2, 8)}`;
  const getMeta = () => ({
    name: props.name,
    status: props.status,
    duration: props.status === "running" ? undefined : (props.duration ?? stoppedAt.value),
    hasIcon: true,
  });
  // 初始就是 error（父层数据先行）时也自动展开一次
  onMounted(() => {
    group?.register(getMeta);
    if (props.status === "error" && props.openOnError && !isOpen.value) {
      setOpen(true);
      autoOpened.value = true;
    }
  });
  onBeforeUnmount(() => {
    group?.unregister(getMeta);
  });

  return {
    id,
    isOpen,
    timeLabel,
    timeMs,
    argsText,
    resultText,
    expanded,
    isLong,
    toggle,
  };
}

import { computed, provide, ref } from "vue";
import { TOOL_CALL_GROUP_KEY } from "./context";
import type { ToolCallGroupProps, ToolCallMeta } from "./types";
import { formatMs } from "../../utils/format";

/**
 * VaToolCallGroup 的状态逻辑：
 * 卡片自动注册 → 汇总运行状态 / 失败数 / 总耗时 → 生成标题。
 */
export function useToolCallGroup(props: ToolCallGroupProps) {
  const getters = ref<Array<() => ToolCallMeta>>([]);

  provide(TOOL_CALL_GROUP_KEY, {
    register: (get) => getters.value.push(get),
    unregister: (get) => {
      const i = getters.value.indexOf(get);
      if (i >= 0) getters.value.splice(i, 1);
    },
  });

  const cards = computed(() => getters.value.map((get) => get()));
  const running = computed(() => cards.value.some((c) => c.status === "running"));
  const failed = computed(() => cards.value.filter((c) => c.status === "error").length);
  const total = computed(() => {
    if (running.value) return undefined;
    if (props.duration != null) return props.duration;
    if (cards.value.length && cards.value.every((c) => c.duration != null)) {
      return cards.value.reduce((t, c) => t + (c.duration ?? 0), 0);
    }
    return undefined;
  });

  const title = computed(() => {
    if (running.value) return props.runningLabel ?? "正在执行工具…";
    const n = cards.value.length;
    const base = props.label ?? `使用了 ${n} 个工具`;
    const bits = [base];
    if (failed.value) bits.push(`${failed.value} 失败`);
    if (total.value != null) bits.push(formatMs(total.value));
    return bits.join(" · ");
  });

  return { cards, running, failed, total, title };
}
